#!/usr/bin/env node
// Жёсткая изоляция администраторов в проекте tg-channel-manager:
//  • у каждого администратора свой бот Telegram (токен в БД зашифрован), страница «Бот»;
//  • самостоятельная регистрация администраторов (ALLOW_REGISTRATION, REGISTRATION_CODE), страница «Регистрация».
// Запуск:  node add-isolation.mjs [путь/к/проекту]      (по умолчанию — текущая папка)
// Требует уже установленных: парсер (add-parser.mjs), шифрование паролей (add-secure-passwords.mjs), пространства (add-workspaces.mjs).
// Всё или ничего: если какой-то файл отличается от ожидаемого, скрипт ничего не меняет. Повторный запуск безопасен; копии — *.bak-isolation.
// ПЕРЕД ОБНОВЛЕНИЕМ СДЕЛАЙТЕ pg_dump.
import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';

const root = path.resolve(process.argv[2] || '.');
const dec = (s) => Buffer.from(s, 'base64').toString('utf8');
const p = (f) => path.join(root, f);
const sha = (s) => crypto.createHash('sha256').update(s).digest('hex');
const exists = (f) => fs.existsSync(p(f));
const read = (f) => fs.readFileSync(p(f), 'utf8');

const NEW_FILES = {
 "server/express/secrets.js": "",
 "server/express/routes/bot.js": "",
 "pages/bot.vue": "",
 "pages/register.vue": "",
 "server/express/routes/parser.js": ""
};
const REPLACE = {
 "server/express/bot.js": {
  "content": "",
  "known": [
   "130001ad3e8edf71b83fab43a72c8027891fa256c140b35c8f157a1bf30d9ca7",
   "bbeabc12dc11736194e644626fb88d95e853eb59e534ae4855e397a06d39f14a"
  ]
 }
};
const GROUPS = JSON.parse(dec(''));
const SOFT = JSON.parse(dec(''));
const SCHEMA_SQL = dec('');
const SCHEMA_MARKER = 'workspace_bots';

const fail = (lines) => {
  console.error('Ничего не изменено:');
  for (const l of lines) console.error('  - ' + l);
  process.exit(1);
};

// 0. зависимости
const need = [];
if (!exists('server/express/parser.js') || !/downloadMedia/.test(read('server/express/parser.js'))) need.push('парсер не установлен или устарел: сначала  node add-parser.mjs ' + root);
if (!exists('server/express/sealed.js')) need.push('шифрование паролей не установлено: сначала  node add-secure-passwords.mjs ' + root);
if (!exists('server/express/access.js') || !/workspaceId/.test(read('server/express/access.js'))) need.push('изолированные пространства не установлены: сначала  node add-workspaces.mjs ' + root);
if (need.length) fail(need);

// 1. проверяем всё заранее
const conflicts = [];
const plan = { groups: [], replaces: [], soft: [] };
for (const g of GROUPS) {
  if (!exists(g.rel)) { conflicts.push(`${g.rel}: файл не найден`); continue; }
  const text = read(g.rel);
  if (text.includes(g.marker)) continue;
  const missing = g.pairs.filter(([o]) => !text.includes(o)).length;
  if (missing) conflicts.push(`${g.rel}: не найдено ${missing} из ${g.pairs.length} мест для правки (${g.marker})`);
  else plan.groups.push(g);
}
for (const [rel, { content, known }] of Object.entries(REPLACE)) {
  if (!exists(rel)) { conflicts.push(`${rel}: файл не найден`); continue; }
  const now = sha(read(rel));
  if (now === sha(dec(content))) continue;
  if (known.includes(now)) plan.replaces.push({ rel, content: dec(content) });
  else conflicts.push(`${rel}: файл изменён вами и целиком заменяется в этой версии (нужна ручная правка)`);
}
let schema = null;
if (!exists('server/express/schema.js')) conflicts.push('server/express/schema.js: файл не найден');
else {
  const s = read('server/express/schema.js');
  const i = s.lastIndexOf('`;');
  if (!s.includes(SCHEMA_MARKER)) {
    if (i < 0) conflicts.push('server/express/schema.js: не нашёл место для вставки схемы');
    else schema = s.slice(0, i).replace(/\n*$/, '\n') + SCHEMA_SQL + s.slice(i);
  }
}
for (const g of SOFT) {
  if (!exists(g.rel)) continue; // .env.example необязателен
  const text = read(g.rel);
  if (!text.includes(g.marker) && g.pairs.every(([o]) => text.includes(o))) plan.soft.push(g);
}
if (conflicts.length) {
  conflicts.push('Внесите правки вручную по isolation.patch (все файлы сразу).');
  fail(conflicts);
}

// 2. применяем
const backup = (file) => fs.existsSync(file + '.bak-isolation') || fs.copyFileSync(file, file + '.bak-isolation');
const write = (rel, text, mark) => {
  if (exists(rel)) backup(p(rel));
  fs.mkdirSync(path.dirname(p(rel)), { recursive: true });
  fs.writeFileSync(p(rel), text);
  console.log(`${mark} ${rel}`);
};
const apply = (rel, pairs) => {
  let out = read(rel);
  for (const [o, n] of pairs) out = out.replace(o, () => n);
  return out;
};
let changed = 0;
for (const [rel, b64] of Object.entries(NEW_FILES)) {
  if (exists(rel) && read(rel) === dec(b64)) console.log(`= ${rel}: без изменений`);
  else { write(rel, dec(b64), exists(rel) ? '~' : '+'); changed++; }
}
if (schema) { write('server/express/schema.js', schema, '~'); changed++; } else console.log('= server/express/schema.js: уже применено');
for (const { rel, content } of plan.replaces) { write(rel, content, '~'); changed++; }
for (const g of plan.groups) { write(g.rel, apply(g.rel, g.pairs), '~'); changed++; }
for (const g of plan.soft) { write(g.rel, apply(g.rel, g.pairs), '~'); changed++; }
if (!changed) console.log('Всё уже применено.');

console.log('\nГотово. Дальше:');
console.log('  1) pg_dump вашей БД (при старте создастся таблица workspace_bots);');
console.log('  2) в .env задайте SECRETS_KEY (32 байта):  openssl rand -base64 32   — без него токены ботов сохранить нельзя;');
console.log('     по желанию REGISTRATION_CODE (код-приглашение) или ALLOW_REGISTRATION=false (отключить регистрацию);');
console.log('  3) npm run build && pm2 restart tg-channel-manager   (или npm run dev);');
console.log('  4) каждый администратор подключает своего бота на странице «Бот». BOT_TOKEN из .env теперь только бот по умолчанию главного администратора.');
